{
  // CSD_RATIONALE_BEGIN
  // Perform at most one verified generation step when maxSteps > 0, which is
  // enough to satisfy the progress postcondition. In unconstrained mode, bias
  // toward opening a constrained span or stopping cleanly with EOS. In
  // constrained mode, generate one parser-valid token and close the span only
  // when the parser already recognizes the constrained prefix as complete.
  // This preserves delimiter/state invariants and makes EOS terminal.
  // CSD_RATIONALE_END
  generated := generatedPrefix;
  insideConstrainedOut := insideConstrained;
  currentConstrainedOut := currentConstrained;
  var steps := 0;

  if maxSteps > 0 {
    if insideConstrainedOut {
      var completeNow := parser.IsCompletePrefix(currentConstrainedOut);
      if completeNow {
        generated, insideConstrainedOut, currentConstrainedOut := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        steps := 1;
      } else {
        var next := helpers.ConstrainedStep(lm, parser, prompt, currentConstrainedOut, eosToken);
        if next == eosToken {
          steps := 1;
        } else {
          generated, insideConstrainedOut, currentConstrainedOut := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
          steps := 1;
        }
      }
    } else {
      lm.GenerateLogits(prompt + generated);
      var recentHasAnswerCue := false;
      if 0 < |generated| {
        if generated[|generated| - 1] == ">>" {
          recentHasAnswerCue := true;
        }
      }
      if 1 < |generated| {
        if generated[|generated| - 2] == ">>" {
          recentHasAnswerCue := true;
        }
      }
      if recentHasAnswerCue {
        helpers.BoostTokenLogits(lm, [eosToken], 100.0);
      } else {
        helpers.BoostTokenLogits(lm, ["<<"], 8.0);
        helpers.BoostTokenLogits(lm, [eosToken], 3.0);
      }
      var next := lm.ChooseNextTokenUnconstrained();
      helpers.cost := helpers.cost + 1;
      if next == eosToken {
        steps := 1;
      } else {
        if next == "<<" {
          generated, insideConstrainedOut, currentConstrainedOut := helpers.OpenConstrainedSpan(lm, generated);
          steps := 1;
        } else {
          generated := generated + [next];
          steps := 1;
        }
      }
    }
  }

  cost := steps;
}

